namespace https.w3id.org.semts.ontology.hash

open DoxAletheia.Rdf_Vocabulary

module semts =
    let _namespace_name = "https://w3id.org/semts/ontology#"

    /// <summary>
    /// Any knowledge that is generated by a comparison of compatible inputs. This might either be raw data or already defined knowledge. A simple example might be the result of a Euclidean distance.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeComparisonMeasure"></see></summary>
    let KnowledgeComparisonMeasure =
        Namespaced_IRI.parse _namespace_name "KnowledgeComparisonMeasure" |> NamespacedName

    /// <summary>
    /// Defines a knowledge generation entity, which corresponds to method-based solution. Compared to other knowledge generation entities this class is a subclass of Algorithm and thus can be linked to algorithmic details.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGenerationMethod"></see></summary>
    let KnowledgeGenerationMethod =
        Namespaced_IRI.parse _namespace_name "KnowledgeGenerationMethod" |> NamespacedName

    /// <summary>
    /// To complement any knowledge that is generated via analytical methods, this class represents knowledge generated from reasoning processes. This also includes validation processes from human experts or results from reasoning tools.
    /// While many analysis results can be regarded unvalidated predictions, this class defines subsequent evaluations to further derive concrete facts or confirmations.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeReasoning"></see></summary>
    let KnowledgeReasoning =
        Namespaced_IRI.parse _namespace_name "KnowledgeReasoning" |> NamespacedName

    /// <summary>
    /// Refers to any algorithmic solution in the context of time series analysis. While this class extends the mls:Algorithm class, it enables a reference to further details on specific task specifics and experiments. It is considered method knowledge as this class can be used to define knowledge about an appropriate or optimal algorithmic solution associated with a time series segment.
    /// <see href="https://w3id.org/semts/ontology#Algorithm"></see></summary>
    let Algorithm = Namespaced_IRI.parse _namespace_name "Algorithm" |> NamespacedName

    /// <summary>
    /// Any knowledge that defines an appropriate setting, regarding a particular method that is beneficial or even optimal when analyzing a segment given a particular task.
    /// <see href="https://w3id.org/semts/ontology#MethodKnowledge"></see></summary>
    let MethodKnowledge =
        Namespaced_IRI.parse _namespace_name "MethodKnowledge" |> NamespacedName

    /// <summary>
    /// A hyperparameter is considered method knowledge as this class can be used to define knowledge about an appropriate or optimal hyperparameter setting associated with the analysis of a time series segment for a concrete task.
    /// <see href="https://w3id.org/semts/ontology#Hyperparameter"></see></summary>
    let Hyperparameter =
        Namespaced_IRI.parse _namespace_name "Hyperparameter" |> NamespacedName

    /// <summary>
    /// A time series segment that does not, or only partially refer to concrete time series data. It represents an artificially generated time series segment that might for instance describe the result of a forecast with a time index not being in the range of the original time series data.
    /// <see href="https://w3id.org/semts/ontology#ArtificialTimeSeriesSegment"></see></summary>
    let ArtificialTimeSeriesSegment =
        Namespaced_IRI.parse _namespace_name "ArtificialTimeSeriesSegment" |> NamespacedName

    /// <summary>
    /// Represents a segment (also referred to as slice) of a uni- or multivariate time series. Any segment can correspond to the whole time series, a subintervall potentially further limited to a subset of dimensions or only to a single data point. This class inherits from dcat:Dataset and is enriched by an additional time index, information about represented data dimensions and information about associated time series knowledge.
    /// <see href="https://w3id.org/semts/ontology#TimeSeriesSegment"></see></summary>
    let TimeSeriesSegment =
        Namespaced_IRI.parse _namespace_name "TimeSeriesSegment" |> NamespacedName

    /// <summary>
    /// Defines a data dimension (or also referred to as feature or attribute) in a time series segment.
    /// <see href="https://w3id.org/semts/ontology#DataDimension"></see></summary>
    let DataDimension =
        Namespaced_IRI.parse _namespace_name "DataDimension" |> NamespacedName

    /// <summary>
    /// Defines any knowledge that is derived from the data. This includes statistics, other signal characteristics or knowledge generated thorugh data analysis methods. Examples for the latter case are predictions, anomalies or cluster group memberships.
    /// <see href="https://w3id.org/semts/ontology#DataKnowledge"></see></summary>
    let DataKnowledge =
        Namespaced_IRI.parse _namespace_name "DataKnowledge" |> NamespacedName

    /// <summary>
    /// Represents the highest level of any knowledge associated with time series data. Knowledge can be made more specific via subclasses or associated concepts.
    /// <see href="https://w3id.org/semts/ontology#Knowledge"></see></summary>
    let Knowledge = Namespaced_IRI.parse _namespace_name "Knowledge" |> NamespacedName

    /// <summary>
    /// A grouping of knowledge which itself is again considered knowledge. Can be used to structure knowledge and create hierarchies.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGroup"></see></summary>
    let KnowledgeGroup =
        Namespaced_IRI.parse _namespace_name "KnowledgeGroup" |> NamespacedName

    /// <summary>
    /// Defines any knowledge that is associated with a particular scenario or domain. Scenario knowledge corresponds to validated expert knowledge or scenario-specific facts. It includes simple notes, predefined labels or mathematical expressions describing the underlying time series data.
    /// <see href="https://w3id.org/semts/ontology#ScenarioKnowledge"></see></summary>
    let ScenarioKnowledge =
        Namespaced_IRI.parse _namespace_name "ScenarioKnowledge" |> NamespacedName

    /// <summary>
    /// Refers to a value that is directly stored in the knowledge graph. Compared to referenced values, these values are rather single, non-complex values having a primitive type.
    /// One example could be the mean value of a univariate time series.
    /// <see href="https://w3id.org/semts/ontology#EmbeddedValue"></see></summary>
    let EmbeddedValue =
        Namespaced_IRI.parse _namespace_name "EmbeddedValue" |> NamespacedName

    /// <summary>
    /// This abstract class serves as parental class of EmbeddedValue and ReferencedValue.
    /// <see href="https://w3id.org/semts/ontology#Value"></see></summary>
    let Value = Namespaced_IRI.parse _namespace_name "Value" |> NamespacedName

    /// <summary>
    /// Relates a concept for a Knowledge instance. Can be used to assign concrete instances from the SemTS taxonomy.
    /// <see href="https://w3id.org/semts/ontology#knowledgeConcept"></see></summary>
    let knowledgeConcept =
        Namespaced_IRI.parse _namespace_name "knowledgeConcept" |> NamespacedName

    /// <summary>
    /// Represents the highest entity to define the process of knowledge generation. A more specific description can be provided by subclasses or assigned concepts. This class inherits from prov:Agent and thus allows for provenance during knowledge propagation.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGenerationEntity"></see></summary>
    let KnowledgeGenerationEntity =
        Namespaced_IRI.parse _namespace_name "KnowledgeGenerationEntity" |> NamespacedName

    /// <summary>
    /// An SKOS concept associated with the knowledge class or any corresponding subclass
    /// <see href="https://w3id.org/semts/ontology#KnowledgeConcept"></see></summary>
    let KnowledgeConcept =
        Namespaced_IRI.parse _namespace_name "KnowledgeConcept" |> NamespacedName

    /// <summary>
    /// An SKOS concept associated with the knowledge generation entity class or any corresponding subclass
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGenerationConcept"></see></summary>
    let KnowledgeGenerationConcept =
        Namespaced_IRI.parse _namespace_name "KnowledgeGenerationConcept" |> NamespacedName

    /// <summary>
    /// Defines any input and output of a knowledge generation entity. It inherits from prov:Entity to define instances that are used by or generated by a prov:Activity, which in turn is the parental class of a knowledge generation entity.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGenerationIO"></see></summary>
    let KnowledgeGenerationIO =
        Namespaced_IRI.parse _namespace_name "KnowledgeGenerationIO" |> NamespacedName

    /// <summary>
    /// Defines the input of a knowledge generation entity. While outputs can only contain produced knowledge, inputs might either reference knowledge or raw data.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGenerationInput"></see></summary>
    let KnowledgeGenerationInput =
        Namespaced_IRI.parse _namespace_name "KnowledgeGenerationInput" |> NamespacedName

    /// <summary>
    /// Defines the output of a knowledge generation entity. Compared to inputs, outputs only allow for a reference to generated knowledge and not to raw data. This, on purpose, excludes data transformations from the overall ontology concept by only focusing on a propagation of knowledge.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeGenerationOutput"></see></summary>
    let KnowledgeGenerationOutput =
        Namespaced_IRI.parse _namespace_name "KnowledgeGenerationOutput" |> NamespacedName

    /// <summary>
    /// References any knowledge within a particular knowledge group.
    /// <see href="https://w3id.org/semts/ontology#groupKnowledge"></see></summary>
    let groupKnowledge =
        Namespaced_IRI.parse _namespace_name "groupKnowledge" |> NamespacedName

    /// <summary>
    /// Defines the goodness or confidence of time series knowledge associated with one or multiple segments. For knowledge produced by a knowledge generation method the quality measure is often equal to the evaluation metric of the generation method, which is why this class inherits from mls:EvaluationMeasure.
    /// <see href="https://w3id.org/semts/ontology#KnowledgeQualityMeasure"></see></summary>
    let KnowledgeQualityMeasure =
        Namespaced_IRI.parse _namespace_name "KnowledgeQualityMeasure" |> NamespacedName

    /// <summary>
    /// This class describes a trained model in the traditional machine learning sense. It inherits from mls:Model and serves as a knowledge entity for subsequent predictions.
    /// <see href="https://w3id.org/semts/ontology#ModelInstance"></see></summary>
    let ModelInstance =
        Namespaced_IRI.parse _namespace_name "ModelInstance" |> NamespacedName

    /// <summary>
    /// Defines analytical, data-specific insights including derived statistics or other structural characteristics such as representative kernel expressions. Knowledge of this class mostly equals extracted data features.
    /// <see href="https://w3id.org/semts/ontology#SegmentDataCharacteristic"></see></summary>
    let SegmentDataCharacteristic =
        Namespaced_IRI.parse _namespace_name "SegmentDataCharacteristic" |> NamespacedName

    /// <summary>
    /// Defines knowledge derived from data-driven analyses. This for instance includes anomalies and predictions.
    /// <see href="https://w3id.org/semts/ontology#SegmentPrediction"></see></summary>
    let SegmentPrediction =
        Namespaced_IRI.parse _namespace_name "SegmentPrediction" |> NamespacedName

    /// <summary>
    /// SegmentRelation defines relations between multiple segment. Such a relation could for instance be a cross-correlation or the result of a distance metric.
    /// <see href="https://w3id.org/semts/ontology#SegmentRelation"></see></summary>
    let SegmentRelation =
        Namespaced_IRI.parse _namespace_name "SegmentRelation" |> NamespacedName

    /// <summary>
    /// An SKOS concept associated with the quality measure class
    /// <see href="https://w3id.org/semts/ontology#QualityMeasureConcept"></see></summary>
    let QualityMeasureConcept =
        Namespaced_IRI.parse _namespace_name "QualityMeasureConcept" |> NamespacedName

    /// <summary>
    /// Refers to a value that is of arbitrary complexity and not directly stored in the knowledge graph. This class inherits from dcat:Dataset and can be retrieved by the associated metainformation. One example could be a set of generated shapelets defining representative segments of a time series.
    /// <see href="https://w3id.org/semts/ontology#ReferencedValue"></see></summary>
    let ReferencedValue =
        Namespaced_IRI.parse _namespace_name "ReferencedValue" |> NamespacedName

    /// <summary>
    /// Relationship to the Value class and thus to allow for a reference to stored data.
    /// <see href="https://w3id.org/semts/ontology#hasValue"></see></summary>
    let hasValue = Namespaced_IRI.parse _namespace_name "hasValue" |> NamespacedName

    /// <summary>
    /// Specifies the column index of a time series segment within a data file or database, in case a source contains multiple time series (e.g. nested dataframes)
    /// <see href="https://w3id.org/semts/ontology#datasetColumnIndex"></see></summary>
    let datasetColumnIndex =
        Namespaced_IRI.parse _namespace_name "datasetColumnIndex" |> NamespacedName

    /// <summary>
    /// Specifies the row index of a time series segment within a data file or database, in case a source contains multiple time series (e.g. nested dataframes)
    /// <see href="https://w3id.org/semts/ontology#datasetRowIndex"></see></summary>
    let datasetRowIndex =
        Namespaced_IRI.parse _namespace_name "datasetRowIndex" |> NamespacedName

    /// <summary>
    /// Can be used to optionally add a description to an entity of the domain.
    /// <see href="https://w3id.org/semts/ontology#description"></see></summary>
    let description =
        Namespaced_IRI.parse _namespace_name "description" |> NamespacedName

    /// <summary>
    /// Specifies the position of the associated dimension within a dataframe or similar ordered data structures.
    /// <see href="https://w3id.org/semts/ontology#dimensionPosition"></see></summary>
    let dimensionPosition =
        Namespaced_IRI.parse _namespace_name "dimensionPosition" |> NamespacedName

    /// <summary>
    /// Property reusing prov:generated
    /// <see href="https://w3id.org/semts/ontology#generated"></see></summary>
    let generated = Namespaced_IRI.parse _namespace_name "generated" |> NamespacedName

    /// <summary>
    /// Assigns a qudt:Datatype instance to an instance of a Value subclass or DataDimension
    /// <see href="https://w3id.org/semts/ontology#hasDatatype"></see></summary>
    let hasDatatype =
        Namespaced_IRI.parse _namespace_name "hasDatatype" |> NamespacedName

    /// <summary>
    /// dimensionUnit is the relation, which assigns a qudt:Unit instance to a DataDimension or a subclass of Value
    /// <see href="https://w3id.org/semts/ontology#hasUnit"></see></summary>
    let hasUnit = Namespaced_IRI.parse _namespace_name "hasUnit" |> NamespacedName

    /// <summary>
    /// Defines the relation from a Knowledge Generation Input to a Time Series Segment and thus to metadata which specifies the underlying data.
    /// <see href="https://w3id.org/semts/ontology#inputDataReference"></see></summary>
    let inputDataReference =
        Namespaced_IRI.parse _namespace_name "inputDataReference" |> NamespacedName

    /// <summary>
    /// Similar to the Input Data Reference, this relation defines all the knowledge associated with the input of a Knowledge Generation Entity.
    /// <see href="https://w3id.org/semts/ontology#inputKnowledge"></see></summary>
    let inputKnowledge =
        Namespaced_IRI.parse _namespace_name "inputKnowledge" |> NamespacedName

    /// <summary>
    /// Defines a hierarchic relationship between time series segments. The intuition of this property is to differentiate between complete time series, in a sense that it includes the data from start to end and subsegments which are reduced in time or dimensionality and thus can be considered a slice of this original data.
    /// <see href="https://w3id.org/semts/ontology#isPartOf"></see></summary>
    let isPartOf = Namespaced_IRI.parse _namespace_name "isPartOf" |> NamespacedName

    /// <summary>
    /// Relates a concept for a Knowledge Generation instance.
    /// <see href="https://w3id.org/semts/ontology#knowledgeGenerationConcept"></see></summary>
    let knowledgeGenerationConcept =
        Namespaced_IRI.parse _namespace_name "knowledgeGenerationConcept" |> NamespacedName

    /// <summary>
    /// Relates the Knowledge Generation Entity, which produced this Knowledge instance.
    /// <see href="https://w3id.org/semts/ontology#knowledgeGenerationEntity"></see></summary>
    let knowledgeGenerationEntity =
        Namespaced_IRI.parse _namespace_name "knowledgeGenerationEntity" |> NamespacedName

    /// <summary>
    /// Allows to assign a quality measure to instantiated knowledge.
    /// <see href="https://w3id.org/semts/ontology#knowledgeQualityMeasure"></see></summary>
    let knowledgeQualityMeasure =
        Namespaced_IRI.parse _namespace_name "knowledgeQualityMeasure" |> NamespacedName

    /// <summary>
    /// Relates any shared Knowledge available for a set of instances from the class Time Series Segment. One example is the generation of Knowledge that is not specific to a single, but to a group of time series segments.
    /// <see href="https://w3id.org/semts/ontology#multiSegmentKnowledge"></see></summary>
    let multiSegmentKnowledge =
        Namespaced_IRI.parse _namespace_name "multiSegmentKnowledge" |> NamespacedName

    /// <summary>
    /// Opposed to Input Knowledge, this property defines the knowledge included in the output of a Knowledge generation Entity.
    /// <see href="https://w3id.org/semts/ontology#outputKnowledge"></see></summary>
    let outputKnowledge =
        Namespaced_IRI.parse _namespace_name "outputKnowledge" |> NamespacedName

    /// <summary>
    /// Defines the concept of a particular Knowledge Quality Measure.
    /// <see href="https://w3id.org/semts/ontology#qualityMeasureConcept"></see></summary>
    let qualityMeasureConcept =
        Namespaced_IRI.parse _namespace_name "qualityMeasureConcept" |> NamespacedName

    /// <summary>
    /// Defines the dimensions associated with a Time Series Segment. Multiple dimensions indicate that the segment corresponds to a multivariate time series.
    /// <see href="https://w3id.org/semts/ontology#segmentDimension"></see></summary>
    let segmentDimension =
        Namespaced_IRI.parse _namespace_name "segmentDimension" |> NamespacedName

    /// <summary>
    /// Defines the index associated with a Time Series Segment. Inherits from the time:TemporalEntity.
    /// <see href="https://w3id.org/semts/ontology#segmentIndex"></see></summary>
    let segmentIndex =
        Namespaced_IRI.parse _namespace_name "segmentIndex" |> NamespacedName

    /// <summary>
    /// Relates any Knowledge available for a particular Time Series Segment.
    /// <see href="https://w3id.org/semts/ontology#segmentKnowledge"></see></summary>
    let segmentKnowledge =
        Namespaced_IRI.parse _namespace_name "segmentKnowledge" |> NamespacedName

    /// <summary>
    /// Can be used to optionally add a title to an entity of the domain.
    /// <see href="https://w3id.org/semts/ontology#title"></see></summary>
    let title = Namespaced_IRI.parse _namespace_name "title" |> NamespacedName
    /// <summary>
    /// Property reusing prov:used
    /// <see href="https://w3id.org/semts/ontology#used"></see></summary>
    let used = Namespaced_IRI.parse _namespace_name "used" |> NamespacedName

    /// <summary>
    /// The string representation for a concrete value of an Embedded Value. Complementary, the actual data type is defined via the dType property.
    /// <see href="https://w3id.org/semts/ontology#valueString"></see></summary>
    let valueString =
        Namespaced_IRI.parse _namespace_name "valueString" |> NamespacedName

    /// <summary>
    /// Property reusing prov:wasDerivedFrom
    /// <see href="https://w3id.org/semts/ontology#wasDerivedFrom"></see></summary>
    let wasDerivedFrom =
        Namespaced_IRI.parse _namespace_name "wasDerivedFrom" |> NamespacedName
